-- 4. 나머지 마스터: 문서분류 01~04 × 고유 Task ID
INSERT INTO CSPD002TG (INPT_MST_SRNO, INPT_ELMT_ID, IMEX_HIS_CD, INPT_BL_GRP_NO, INPT_TASK_ID, AI_INPT_PAPS_QLT_SCRE, TRN_LOG_SRNO, LST_DB_CHG_ID, LST_DB_CHG_DTM)
SELECT M.INPT_MST_SRNO, 'ELMT' || M.INPT_MST_SRNO || C.IMEX_HIS_CD, C.IMEX_HIS_CD, M.INPT_BL_GRP_NO, TO_CHAR(M.INPT_MST_SRNO) || C.IMEX_HIS_CD, 92.0, TO_CHAR(M.INPT_MST_SRNO) || C.IMEX_HIS_CD, 'SYSTEM', '20250115120000'
  FROM CSPD001TM M
 CROSS JOIN (SELECT '01' AS IMEX_HIS_CD FROM DUAL UNION ALL SELECT '02' FROM DUAL UNION ALL SELECT '03' FROM DUAL UNION ALL SELECT '04' FROM DUAL) C
 WHERE M.INPT_MST_SRNO BETWEEN 10002 AND 30005;

INSERT INTO CSPD003TF (INPT_MST_SRNO, AI_INPT_TOTALTEXT_SRNO, INPT_TASK_ID, BFRS_AICR_EXTC_TXT, INPT_SANCTION_DAT_TXT, AI_INPT_SANCTION_RULE_TXT, AI_INPT_TOTALTEXT_RVSN_YN, AI_INPT_ALT_YN, ITM_INPT_XAXIS_STA_CRDN_CN, ITM_INPT_YAXIS_STA_CRDN_CN, ITM_INPT_XAXIS_END_CRDN_CN, ITM_INPT_YAXIS_END_CRDN_CN, LST_DB_CHG_ID, LST_DB_CHG_DTM)
SELECT M.INPT_MST_SRNO, M.INPT_MST_SRNO * 100 + TO_NUMBER(C.IMEX_HIS_CD), TO_CHAR(M.INPT_MST_SRNO) || C.IMEX_HIS_CD, 'TotalText doc' || C.IMEX_HIS_CD || ' ' || M.INPT_MST_SRNO, 'SANCTION ' || M.INPT_MST_SRNO, 'RULE_OK', 'N', NVL(M.ALERT_YN, 'N'), 100, 100, 500, 200, 'SYSTEM', '20250115120000'
  FROM CSPD001TM M
 CROSS JOIN (SELECT '01' AS IMEX_HIS_CD FROM DUAL UNION ALL SELECT '02' FROM DUAL UNION ALL SELECT '03' FROM DUAL UNION ALL SELECT '04' FROM DUAL) C
 WHERE M.INPT_MST_SRNO BETWEEN 10002 AND 30005;

COMMIT;
